result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/hex.ts", "content": "/**
 * Axial hex-grid math (pointy-top convention, "q + r" axial coordinates).
 *
 * Internally we use cube coordinates (x, y, z) with x + y + z === 0 for
 * algorithms that are cleaner there, converting from/to axial as needed.
 */

export interface Hex {
  q: number;
  r: number;
}

export const hex = (q: number, r: number): Hex => ({ q, r });

/** Axial -> cube. */
export const toCube = (h: Hex): { x: number; y: number; z: number } => ({
  x: h.q,
  y: -h.q - h.r,
  z: h.r,
});

/** Cube -> axial. */
export const fromCube = (c: { x: number; y: number; z: number }): Hex => ({
  q: c.x,
  r: c.z,
});

export const equals = (a: Hex, b: Hex): boolean => a.q === b.q && a.r === b.r;

export const key = (h: Hex): string => `${h.q},${h.r}`;

const CUBE_DIRECTIONS: ReadonlyArray<{ x: number; y: number; z: number }> = [
  { x: 1, y: -1, z: 0 },
  { x: 1, y: 0, z: -1 },
  { x: 0, y: 1, z: -1 },
  { x: -1, y: 1, z: 0 },
  { x: -1, y: 0, z: 1 },
  { x: 0, y: -1, z: 1 },
];

/** The 6 neighbors of `center`, in clockwise order starting at (+1, 0). */
export function neighbors(center: Hex): Hex[] {
  return CUBE_DIRECTIONS.map((d) => hex(center.q + d.x, center.r + d.z));
}

/** Hex distance in cube metric. */
export function distance(a: Hex, b: Hex): number {
  const ca = toCube(a);
  const cb = toCube(b);
  return Math.max(
    Math.abs(ca.x - cb.x),
    Math.abs(ca.y - cb.y),
    Math.abs(ca.z - cb.z),
  );
}

/** All hexes exactly `radius` away from `center` (clockwise ring). radius must be >= 0. */
export function ring(center: Hex, radius: number): Hex[] {
  if (radius < 0) throw new RangeError(`ring radius must be >= 0, got ${radius}`);
  if (radius === 0) return [hex(center.q, center.r)];

  const results: Hex[] = [];
  // Start at center + direction[4] * radius, then walk each direction.
  const startDir = CUBE_DIRECTIONS[4];
  let current = hex(center.q + startDir.x * radius, center.r + startDir.z * radius);

  for (let side = 0; side < 6; side++) {
    const d = CUBE_DIRECTIONS[side];
    for (let step = 0; step < radius; step++) {
      results.push(current);
      current = hex(current.q + d.x, current.r + d.z);
    }
  }
  return results;
}

/** All hexes within `radius` of `center`, including the center itself. */
export function spiral(center: Hex, radius: number): Hex[] {
  if (radius < 0) throw new RangeError(`spiral radius must be >= 0, got ${radius}`);
  const results: Hex[] = [hex(center.q, center.r)];
  for (let k = 1; k <= radius; k++) {
    results.push(...ring(center, k));
  }
  return results;
}

function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t;
}

function cubeLerp(
  a: { x: number; y: number; z: number },
  b: { x: number; y: number; z: number },
  t: number,
): { x: number; y: number; z: number } {
  return {
    x: lerp(a.x, b.x, t),
    y: lerp(a.y, b.y, t),
    z: lerp(a.z, b.z, t),
  };
}

function cubeRound(c: { x: number; y: number; z: number }): { x: number; y: number; z: number } {
  let rx = Math.round(c.x);
  let ry = Math.round(c.y);
  let rz = Math.round(c.z);

  const dx = Math.abs(rx - c.x);
  const dy = Math.abs(ry - c.y);
  const dz = Math.abs(rz - c.z);

  if (dx > dy && dx > dz) {
    rx = -ry - rz;
  } else if (dy > dz) {
    ry = -rx - rz;
  } else {
    rz = -rx - ry;
  }
  return { x: rx, y: ry, z: rz };
}

/**
 * Line from `a` to `b` inclusive via cube-space lerp and rounding.
 * Returns distance(a,b) + 1 hexes.
 */
export function line(a: Hex, b: Hex): Hex[] {
  const n = distance(a, b);
  if (n === 0) return [hex(a.q, a.r)];

  const ca = toCube(a);
  const cb = toCube(b);
  const results: Hex[] = [];

  // Nudge slightly toward a at t=1 to break ties deterministically.
  for (let i = 0; i <= n; i++) {
    const t =
      n === 0 ? 0 : Math.max(Math.min(i / n, 1), 0) - Number.EPSILON * (i / n === 1 ? 1 : 0);
    const c = cubeRound(cubeLerp(ca, cb, i === n ? t : i / n));
    results.push(fromCube(c));
  }
  return results;
}
