result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/tests/hex.test.ts", "content": "import { describe, expect, it } from 'vitest';
import { distance, hex, key, line, neighbors, ring, spiral } from '../src/hex';

describe('distance', () => {
  it('distance((0,0),(2,-1)) === 2', () => {
    expect(distance(hex(0, 0), hex(2, -1))).toBe(2);
  });

  it('is symmetric and zero to itself', () => {
    const a = hex(-3, 7);
    const b = hex(4, -2);
    expect(distance(a, b)).toBe(distance(b, a));
    expect(distance(a, a)).toBe(0);
  });
});

describe('neighbors', () => {
  it('returns exactly 6 unique hexes at distance 1', () => {
    const center = hex(3, -5);
    const ns = neighbors(center);
    expect(ns).toHaveLength(6);
    for (const n of ns) {
      expect(distance(center, n)).toBe(1);
    }
  });
});

describe('ring', () => {
  it('radius 2 returns exactly 12 unique hexes all at distance 2', () => {
    const center = hex(0, 0);
    const cells = ring(center, 2);
    expect(cells).toHaveLength(12);

    const keys = new Set(cells.map(key));
    expect(keys.size).toBe(12); // no duplicates

    for (const c of cells) {
      expect(distance(center, c)).toBe(2);
    }
  });

  it('ring radius 0 is just the center; ring radius 1 has 6 hexes', () => {
    expect(ring(hex(2, 3), 0)).toEqual([hex(2, 3)]);
    expect(ring(hex(2, 3), 1)).toHaveLength(6);
  });
});

describe('spiral', () => {
  it('radius 2 returns 19 hexes (1 + 6 + 12) with no duplicates', () => {
    const cells = spiral(hex(0, 0), 2);
    expect(cells).toHaveLength(19); // 1 + 6 + 12

    const keys = new Set(cells.map(key));
    expect(keys.size).toBe(19);
  });

  it('covers exactly the set of hexes within radius', () => {
    const center = hex(-1, 4);
    const cells = new Set(spiral(center, 3).map(key));
    for (let q = -10; q <= 10; q++) {
      for (let r = -10; r <= 10; r++) {
        const h = hex(q, r);
        const within = distance(center, h) <= 3;
        expect(cells.has(key(h))).toBe(within);
      }
    }
  });
});

describe('every hex property sweep', () => {
  const sample: Array<[number, number]> = [
    [0, 0],
    [1, -2],
    [-4, 3],
    [7, 7],
    [-9, 0],
  ];

  it('every sampled hex has exactly 6 neighbors at distance 1', () => {
    for (const [q, r] of sample) {
      const ns = neighbors(hex(q, r));
      expect(new Set(ns.map(key)).size).toBe(6);
      for (const n of ns) {
        expect(distance(hex(q, r), n)).toBe(1);
      }
    }
  });
});

describe('line', () => {
  it('has length distance+1 with consecutive entries adjacent', () => {
    const pairs: Array<[ReturnType<typeof hex>, ReturnType<typeof hex>]> = [
      [hex(0, 0), hex(2, -1)],
      [hex(-3, 5), hex(4, -6)],
      [hex(0, 0), hex(-5, -5)],
      [hex(2, 2), hex(2, -3)],
      [hex(1, -1), hex(1, -1)], // degenerate
    ];
    for (const [a, b] of pairs) {
      const l = line(a, b);
      expect(l).toHaveLength(distance(a, b) + 1);
      expect(l[0]).toEqual(a);
      expect(l[l.length - 1]).toEqual(b);
      for (let i = 0; i < l.length - 1; i++) {
        expect(distance(l[i], l[i + 1])).toBe(1);
      }
    }
  });
});
"})
